# THE PLAN of one watering with can id: double[] { side, wet seconds (can.waterSec), water used per watering (bar points; 0 = never runs dry),
# Growth Boost % of a standard crop (ceiling can.growMax), Bloom %, Capacity / Growth / (retired) / Bloom / Rich Soil levels, Miracle %, Dew %,
# can fertilizer game seconds }. Only YOUR lifelong can uses its points + can:bonus (a found / foreign / plain one: none). Levels = inside the cap
M(gcan, r"""
public static double[] plan(java.util.UUID u, String id, @BD@ d, double maxDur) {
  double sd = (double) sideOf(id);
  double us = (double) usesOf(id);
  java.util.Properties P = null;
  if (u != null && @PKG@.GearCfg.LL_ON && @PKG@.GearLL.mine(u, d) && !@PKG@.GearLL.rbWait(u)) {
    P = @PKG@.GearLL.reg(@PKG@.Gear.pkey(u));
    if (@PKG@.GearLL.bad(P)) P = null;
  }
  int k = @PKG@.GearLL.CAN;
  double cap = 0.0;
  double gro = 0.0;
  double blo = 0.0;
  double ric = 0.0;
  double mir = 0.0;
  double dew = 0.0;
  if (P != null) {
    cap = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_CAP);
    gro = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_GROW);
    blo = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_BLOOM);
    ric = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_RICH);
    mir = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_MIRA);
    dew = (double) @PKG@.GearLL.perkEff(u, P, k, @PKG@.GearLL.PK_DEW);
    Object bo = @PKG@.Gear.bget("can:bonus:" + u);
    if (bo != null) {
      cap = cap + bonus(bo, "cap");
      gro = gro + bonus(bo, "grow");
      blo = blo + bonus(bo, "bloom");
      ric = ric + bonus(bo, "rich");
      mir = mir + bonus(bo, "mira");
      dew = dew + bonus(bo, "dew");
    }
  }
  double mx = maxDur > 0.0 ? maxDur : 100.0;
  double use = @PKG@.GearLL.canTop(id) ? 0.0 : mx / (us * (1.0 + cap * @PKG@.GearCfg.CAN_CAPP / 100.0));          // Skyy "Only top can"
  double g = Math.min(gro * @PKG@.GearCfg.CAN_GROW, @PKG@.GearCfg.CAN_GMAX);
  double b = Math.min(blo * @PKG@.GearCfg.CAN_BLOOM, 100.0);
  double fs = (double) @PKG@.GearCfg.CAN_FSEC * (1.0 + Math.min(ric * @PKG@.GearCfg.CAN_RICH, 300.0) / 100.0);
  double mp = Math.min(mir * @PKG@.GearCfg.CAN_MIRA, @PKG@.GearCfg.CAN_MIRMAX);
  double dp = Math.min(dew * @PKG@.GearCfg.CAN_DEW, 100.0);
  return new double[] { sd, (double) @PKG@.GearCfg.CAN_SEC, use, g < 0.0 ? 0.0 : g, b, cap, gro, 0.0, blo, ric, mp, dp, fs };
}""")
